// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to avoid overflow issues
        amount = bound(amount, 0, type(uint256).max - 1);
        // Call the function under test
        c.AdjustBetAmounts(amount);
        // The public getter currentBetLimit() returns the stored betLimit
        assertTrue(c.currentBetLimit() == amount);
    }
}

